def turn(question, *requirements, outcome='answer', tools=None, reads=None, choice=None):
    return dict(question=question, requirements=[{'id': f'r{i}', 'text': r}
                for i, r in enumerate(requirements, 1)], outcome=outcome,
                allowed_tools=tools, required_reads=reads or [], choice=choice)


def compile_bank():
    cases = []
    def add(group, question, requirements, *, inn=A, setup=None, outcome='answer', tools=None, reads=None, tags=()):
        turns = question if isinstance(question, list) else [turn(question, *requirements, outcome=outcome, tools=tools, reads=reads)]
        n = sum(c['category'] == group for c in cases) + 1
        case = dict(id=f'{group}{n:02}', category=group, primary_inn=inn,
                    setup=[turn(q, 'Подготовить указанный проверенный контекст.') for q in setup or []],
                    turns=turns, tags=list(tags), split='holdout' if (len(cases)+1)%5 == 0 else 'development')
        cases.append(case)
    def rows(group, text, *, inns=None, setup=None, outcome='answer', tools=None):
        for i, line in enumerate(text.strip().splitlines()):
            q, *requirements = line.split('|')
            inn = (inns or GENERAL)[i % len(inns or GENERAL)]
            other = B if inn != B else A
            third = C if C not in (inn, other) else '9705152496'
            add(group, q.replace('<A>', inn).replace('<B>', other).replace('<C>', third), requirements,
                inn=inn, setup=[s.replace('<A>',inn) for s in setup or []], outcome=outcome, tools=tools)

