def validate(bank):
    expected = {'G':15,'F':20,'L':15,'N':10,'R':15,'S':15,'E':10,'C':30,'M':20}
    assert dict(Counter(c['category'] for c in bank['cases'])) == expected
    assert len({c['id'] for c in bank['cases']}) == 150
    assert sum(c['split']=='holdout' for c in bank['cases']) == 30
    for case in bank['cases']:
        assert (3 <= len(case['turns']) <= 6) if case['category']=='M' else len(case['turns'])==1
        for t in case['turns']:
            assert t['question'] and t['requirements'] and all(r['text'] for r in t['requirements'])
        if case['category']=='C': assert len(case['turns'][0]['requirements']) >= 2


def load():
    bank=json.loads(BANK.read_text())
    if bank != compile_bank(): raise ValueError('Defense bank drift; compile and review before running')
    return bank


if __name__ == '__main__':
    p=argparse.ArgumentParser(); p.add_argument('--check',action='store_true'); args=p.parse_args()
    bank=load() if args.check else compile_bank()
    if not args.check: BANK.write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'cases':len(bank['cases']),'turns':sum(len(c['turns']) for c in bank['cases']),
                      'categories':dict(Counter(c['category'] for c in bank['cases']))}))
